package com.example.payment.integrationtest.architecture;

import static com.tngtech.archunit.core.domain.JavaClass.Predicates.resideInAPackage;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import org.junit.jupiter.api.Test;

class LayerDependencyTest {

  private static final JavaClasses CLASSES =
      new ClassFileImporter()
          .withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
          .importPackages("com.example.payment");

  // Allow-list: pure language core only (no java.io, java.nio, java.net, frameworks).
  private static final String[] LANGUAGE_CORE = {"java.lang..", "java.math..", "java.util.."};

  @Test
  void domainDependsOnlyOnDomainAndLanguageCore() {
    classes()
        .that()
        .resideInAPackage("com.example.payment.domain..")
        .should()
        .onlyDependOnClassesThat(
            resideInAPackage("com.example.payment.domain..")
                .or(resideInAPackage(LANGUAGE_CORE)))
        .check(CLASSES);
  }

  @Test
  void applicationDependsOnlyOnApplicationDomainAndLanguageCore() {
    classes()
        .that()
        .resideInAPackage("com.example.payment.application..")
        .should()
        .onlyDependOnClassesThat(
            resideInAPackage("com.example.payment.application..")
                .or(resideInAPackage("com.example.payment.domain.."))
                .or(resideInAPackage(LANGUAGE_CORE)))
        .check(CLASSES);
  }
}
E
